import re
def readable(s):
 return re.sub(r'\b(HP|turn|point|at|for|of|exact|filmed|source|from|to|draw|with|cards|seconds|Turn|turns|Both)(?=\d)',r'\1 ',s)
def walk(x):
 if isinstance(x,dict):return {k:walk(v) for k,v in x.items()}
 if isinstance(x,list):return [walk(v) for v in x]
 if isinstance(x,str):return readable(x)
 return x
